x_comment('x_Droggn-CardGame',"This card game is a version of #$Tarot-CardGame which developed in #$Austria.  There is a tradition among some of the players that this game was introduced from France or the French part of Switzerland. Some of them called it Franzosisches Tarock, to distinguish it from the Tarock games with 54 cards played in other parts of Austria (#$Konigrufen-CardGame).  Its introduction was said to be associated with Andreas Hofer, the Tyrolean hero who stood against Napoleon.  Others, however, contend that it was imported from northern Italy by Italian door-to-door salesmen ('kraxn-drogar') who used to sell their goods in the Tyrol.  In recent times it seems to be played only in the Stubai valley, south west of Innsbruck.") :- x_cid(a65b1274145951).
