x_comment(x_Oversleeping,"A #$TemporalObjectType and specialization of #$Sleeping and #$Accident.  Each instance of #$Oversleeping is an event in which someone unintentionally sleeps later than intended.  An instance of #$Oversleeping begins at the time (whether precise or approximate) the sleeper intended to wake up, and ends when the sleeper wakes up.  So if I intend to wake up at 7 am but accidentally sleep until 9 am, I am the doer of an #$Oversleeping event with a #$duration of two hours.\n<p>\nNote that #$Oversleeping is orthogonal with #$SleepingLate (q.v.): an event may be an instance of both, but being an instance of one does not entail being an instance of the other.") :- x_cid(a65b1274145965).
