x_comment('x_characteristicActivityTypeOfPersonType-Frequently',"A #$BinaryPredicate and a specialization of #$characteristicActivityTypeOfPersonType.  Where <code>P-TYPE</code> is an instance of #$PersonTypeByActivity and <code>A-TYPE</code> is a specialization of #$Action,\n<pre>\n  (#$characteristicActivityTypeOfPersonType-Frequently <code>P-TYPE A-TYPE</code>)\n</pre>\nmeans that <i>frequently</i> performing instances of <code>A-TYPE</code> is what makes one an instance of <code>P-TYPE</code>.  For example,\n<pre>\n  (#$characteristicActivityTypeOfPersonType-Frequently #$Runner #$Running)\n</pre>\nmeans that frequently performing instances of #$Running is what makes one an instance of #$Runner.  See also #$characteristicActivityTypeOfPersonType-AtLeastOnce and #$characteristicActivityTypeOfPersonType-Presently.") :- x_cid(a65b1274145972).
