x_comment(x_invitee,"A binary role predicate relating instances of #$PurposefulAction to instances of #$Agent-Generic. (#$invitee EVENT AGENT) means that AGENT is either a prospective or actual recipient of an invitation to participate in EVENT.  This is the role played by any agent who happens to be put on a list of invitees for a given event. Note that (#$invitee EVENT AGENT) need not be such that (#$participantStatus AGENT EVENT #$invitedParticipantIn) (q.v.).\nThe latter is temporally qualified: AGENT *acquires* #$invitedParticipantIn after receiving an #$Invitation-IBT as the result of a #$Inviting-CommunicationAct, and\nmay lose it by declinining the invitation.  But the role of #$invitee in an event does not change throughout the event.  Moreover, an invitee need not be an actor or participant in the event.") :- x_cid(a65b1274145979).
