x_comment('x_HungarianTarokk-CardGame',"This card game is a version of #$Tarot-CardGame which developed in the 19th century from a version of #$Zwanzigerrufen-CardGame.  It is generally known as Huszashivasos tarokk (XX-calling tarokk), or Paskievics tarokk after Ivan Fyodorovich Paskevich, the prince of Warsaw who led Russian troops to Hungary to put down the Hungarian revolution and war of independence in 1848/49. Possibly there is some connection between the year '48 and the 48 card points needed to win the game.") :- x_cid(a65b12741459a1).
