x_comment(x_Voting,"An instance of #$TemporalObjectType and a specialization of #$SingleDoerAction and #$Politics.  Each instance of #$Voting is the casting of a vote (or multiple votes) by a single #$IntelligentAgent.   For the notion of the larger-scale 'vote' on an issue (or multiple issues) by all participating members of an #$Organization, see #$Vote-CollectiveDecision.\n<p>\nCommonly, an instance of #$Voting will consist of filling out and submitting a ballot (cf. #$Ballot-CW, #$Ballot-IBO), whereby multiple candidates and/or initiatives are voted for or against.  Any #$properSubEvents of such an event that consist of, e.g., selecting a particular candidate or choosing 'Yes' or 'No' on a particular initiative are instances of #$SelectingBetween, but are not themselves instances of #$Voting.  In the event that only one choice is expressed in an instance of voting (as in, e.g., voting 'Yea' or 'Nay' in a voice vote), the act of expressing that choice is identical with the voting, and hence would be an instance of both #$SelectingBetween and #$Voting.") :- x_cid(a65b12741459a3).
