x_comment(x_AgentTypeByInterest,"A collection of collections.  Each instance of #$AgentTypeByInterest is a collection of #$IntelligentAgents who share an interest in some thing.  These will usually be functionally denoted.  For example, an agent  who likes to collect postage stamps might be a member of (#$HobbyInterestFn #$PostageStamps).  Alternatively, she might be a member of (ProductInterestFn #$PostageStamps) if she wants to use #$PostageStamps to send mail. Use #$hasInterest to relate an instance of #$IntelligentAgent and the instance of #$AgentTypeByInterest to which the agent belongs.") :- x_cid(a65b12741459b5).
