x_comment('x_characteristicActivityTypeOfPersonType-AtLeastOnce',"A #$BinaryPredicate and a specialization of #$characteristicActivityTypeOfPersonType.  Where <code>P-TYPE</code> is an instance of #$PersonTypeByActivity and <code>A-TYPE</code> is a specialization of #$Action,\n<pre>\n  (#$characteristicActivityTypeOfPersonType-AtLeastOnce P-TYPE A-TYPE)\n</pre>\nmeans that performing <i>at least one</i> instance of <code>A-TYPE</code> is what makes one an instance of <code>P-TYPE</code>.  For example,\n<pre>\n(#$characteristicActivityTypeOfPersonType-AtLeastOnce #$Murderer #$Murder)\n</pre>\nmeans that performing at least one instance of #$Murder is what makes one an instance of #$Murderer.  See also #$characteristicActivityTypeOfPersonType-Frequently and #$characteristicActivityTypeOfPersonType-Presently.") :- x_cid(a65b12741459b6).
