x_comment(x_votesForCandidateForPositionInOrg,"A #$QuaternaryPredicate.  Where <code>VOTING</code> is a #$Voting, <code>CANDIDATE</code> is a #$Person, <code>POSITION</code> is a #$PersonTypeByPositionInOrg, and <code>ORG</code> is an #$Organization, <code>(#$votesForCandidateForPositionInOrg VOTING CANDIDATE POSITION ORG)</code> means that in performing <code>VOTING</code>, the performer of <code>VOTING</code> votes for <code>CANDIDATE</code> for <code>POSITION</code> in <code>ORG</code>.  For example,\n<pre>\n(#$votesForCandidateForPositionInOrg BobsVotingIn2004Election #$GeorgeWBush\n#$President-HeadOfGovernmentOrHeadOfState #$UnitedStatesOfAmerica)\n</pre>\nmeans that in performing BobsVotingIn2004Election, the performer of BobsVotingIn2004Election (i.e. Bob) votes for George W. Bush for president of the United States.") :- x_cid(a65b12741459cb).
