x_comment('x_characteristicActivityTypeOfPersonType-Presently',"A #$BinaryPredicate and a specialization of #$characteristicActivityTypeOfPersonType.  Where <code>P-TYPE</code> is an instance of #$PersonTypeByActivity and <code>A-TYPE</code> is a specialization of #$Action,\n<pre>\n  (#$characteristicActivityTypeOfPersonType-Presently P-TYPE A-TYPE)\n</pre>\nmeans that <i>presently</i> performing an instance of <code>A-TYPE</code> is what makes one an instance of <code>P-TYPE</code>.  For example,\n<pre>\n  (#$characteristicActivityTypeOfPersonType-Presently #$Tourist #$Tourism)\n</pre>\nmeans that presently performing an instance of #$Tourism is what makes one an instance of #$Tourist.  (One is only a #$Tourist while one is engaging in #$Tourism.)  See also #$characteristicActivityTypeOfPersonType-AtLeastOnce and #$characteristicActivityTypeOfPersonType-Frequently.") :- x_cid(a65b12741459d8).
