x_comment(x_characteristicActivityTypeOfPersonType,"A #$BinaryPredicate that relates an instance of #$PersonTypeByActivity to a specialization of #$Action.  <code>(#$characteristicActivityTypeOfPersonType P-TYPE A-TYPE)</code> means that performing instances of <code>A-TYPE</code> is what makes one an instance of <code>P-TYPE</code>.  This predicate is neutral with respect to whether it is\n<blockquote>\n(i) having performed <i>at least one</i> instance of <code>A-TYPE</code>;\n<br>\n(ii) <i>frequently</i> performing instances of <code>A-TYPE</code>; or\n<br>\n(iii) <i>presently</i> performing an instance of <code>A-TYPE</code>\n</blockquote>\nthat makes one (presently) an instance of <code>P-TYPE</code>.  For predicates that are <i>not</i> neutral in this respect, see the more specialized #$characteristicActivityTypeOfPersonType-AtLeastOnce, #$characteristicActivityTypeOfPersonType-Frequently, and #$characteristicActivityTypeOfPersonType-Presently.") :- x_cid(a65b12741459f8).
