x_comment(x_accusedOfRoleInEvent,"A ternary predicate that relates an #$Accusing (q..v.) to a #$BinaryRolePredicate to an #$Event.  <code>(#$accusedOfRoleInEvent ACCUSING ROLE EVENT)</code> means that in <code>ACCUSING</code> the #$accused (q.v.) agent is accused of playing <code>ROLE</code> in <code>EVENT</code>.  Usually (but not always), <code>ROLE</code> will be a specialization of #$deliberateActors and <code>EVENT</code> a specialization of #$Action.\n<p>\nSee also the type-level version of this predicate, #$accusedOfRoleInType.") :- x_cid(a65b1274145a10).
