x_comment(x_ApplyingCondimentToFoodOrDrink,"A specialization of #$LocatingInIntendedPosition and #$ImprovementEvent.  Each instance of #$ApplyingCondimentToFoodOrDrink is an event in which an agent adds a #$Condiment to a fully prepared #$FoodOrDrink to improve its flavor.  Examples include salting french fries, adding sugar to coffee, and putting mustard on a hot dog.  Note that this does not include adding ingredients as part of the food or drink's normal preparation process; so it excludes, e.g., using sugar as an ingredient when baking cookies or preparing lemonade, as well as using Caesar salad dressing when preparing a Caesar salad.  It does, however, include (e.g.) adding salad dressing to a garden salad of a sort that is not standardly prepared with dressing.") :- x_cid(a65b1274145a1c).
