x_comment(x_DwarfTossing,"An instance of #$TemporalObjectType and a specialization of #$ThrowingAnObject and #$RecreationalActivity.  Each instance of #$DwarfTossing is part of an event in which participants toss dwarfs<sup>*</sup> (i.e. instances of #$HumanWithDwarfism) onto cushions or mattresses for amusement.  The dwarfs are usually paid for their services, and typically wear special padded clothing for protection.  Instances of #$DwarfTossing typically take place in bars and/or at parties.  #$DwarfTossing has been banned in some places, e.g. #$France, on the ground that it is an affront to human dignity.\n<p>\n<sup>*</sup><i>Sic</i>: 'dwarves' is the appropriate plural form only when referring to the mythical creatures, i.e. the kind in #$LordOfTheRings-Trilogy.") :- x_cid(a65b1274145a20).
