x_comment(x_HoldingWithOneHand,"A specialization of #$HoldingWithHand.  Each instance of #$HoldingWithOneHand is a #$HoldingWithHand event involving exactly one hand.  However, #$HoldingWithOneHand is agnostic as to whether there is another, cotemporal #$HoldingWithOneHand event done by the same performer and holding the same object.  To state specifically that someone is holding an object with two hands, e.g., a #$BaseballBat, use #$HoldingWithBothHands.  To state specifically that someone is holding an object with only one hand, e.g, a #$WritingPen, use #$HoldingWithOnlyOneHand.") :- x_cid(a65b1274145a47).
